import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`airbnb-pricing-optimizer`,hasInputUrl:!0,heroTitle:`Price your Airbnb to fill every night.`,heroSubtitle:`Perplexity Computer studies your market, prices your calendar, and finds your revenue gaps — automatically.`,heroCta:`Optimize My Pricing`,inputUrlCta:`Optimize My Pricing`,inputUrlPlaceholder:`Your Airbnb listing URL`,inputUrlPrefill:`Build a pricing strategy for this short-term rental: {url}. 1) Analyze comparable listings nearby: nightly rates, occupancy, and amenities. 2) Recommend a base price plus seasonal and weekend adjustments. 3) Set minimum-stay and gap-night rules to cut empty nights. 4) Estimate the revenue lift versus my current pricing. 5) Suggest listing improvements that justify a higher rate.`,heroOverlaySteps:[`Study nearby listings' rates, occupancy, and amenities`,`Set a base price with seasonal and weekend adjustments`,`Set minimum-stay and gap-night rules to cut empty nights`,`A pricing calendar — ready to use`],generatingSteps:[`Visiting {url} to get started`,`Designing an agent for your task`,`Configuring the analysis`,`Setting up your deliverable`],featureSectionTitle:`From flat pricing to a full revenue plan`,featureCardTitles:[`Connects to your host stack`,`Outputs that raise your revenue`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Notion, Gmail — Computer builds your pricing plan and revenue tracker in the tools you already use.`,`A pricing calendar. A comp analysis. A revenue-lift estimate. A listing improvement list.`],capabilitySectionTitle:`Your revenue manager, on autopilot`,capabilitySectionSubtitle:`Paste your listing, step away, and come back to a pricing plan and a revenue estimate.`,capabilityCards:[{title:`Comp Analysis`,description:`Computer can study nearby listings' rates, occupancy, and amenities.`},{title:`Pricing Calendar`,description:`Computer can set a base price with seasonal and weekend adjustments.`},{title:`Gap-Night Rules`,description:`Computer can set minimum-stay and gap-night rules to cut empty nights.`},{title:`Connect Your Tools`,description:`Computer can build your pricing plan in Sheets and track revenue in Notion.`},{title:`Remembers Your Listing`,description:`Computer can remember your property and goals for every update.`},{title:`Monitor & Alert`,description:`Computer can watch local demand and flag a night that's priced wrong.`}]});export{t as default};
